//SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract LendingV1 is Initializable, OwnableUpgradeable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // The ERC-20 token used for deposits, borrowing, and repayment.
    IERC20 public token;

    // Total tokens deposited by each user.
    mapping(address => uint256) public deposits;

    // Total outstanding debt for each user.
    mapping(address => uint256) public debts;

    // Initializes the lending contract through the proxy.
    function initialize(address tokenAddress) public initializer {
        require(tokenAddress != address(0), "Invalid token address");

        __Ownable_init(msg.sender);


        token = IERC20(tokenAddress);
    }

    // Deposit tokens into the lending contract.
    function deposit(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be greater than zero");

        token.safeTransferFrom(msg.sender, address(this), amount);

        deposits[msg.sender] += amount;
    }

    // Borrow tokens, subject to a 50% limit on the user's recorded deposits.
    function borrow(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be greater than zero");

        uint256 borrowingLimit = deposits[msg.sender] / 2;

        require(
            debts[msg.sender] + amount <= borrowingLimit,
            "Borrowing limit exceeded"
        );

        require(
            token.balanceOf(address(this)) >= amount,
            "Insufficient liquidity"
        );

        debts[msg.sender] += amount;

        token.safeTransfer(msg.sender, amount);
    }

    // Repay all or part of the user's outstanding debt.
    function repay(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be greater than zero");
        require(debts[msg.sender] >= amount, "Repayment exceeds debt");

        token.safeTransferFrom(msg.sender, address(this), amount);

        debts[msg.sender] -= amount;
    }

    // Returns the amount a user can borrow based on their current records.
    function availableToBorrow(address user)
        external
        view
        returns (uint256)
    {
        uint256 borrowingLimit = deposits[user] / 2;

        if (debts[user] >= borrowingLimit) {
            return 0;
        }

        return borrowingLimit - debts[user];
    }
}

